import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Footer from '../components/Footer';

const PaymentPage = () => {
    const navigate = useNavigate();
    const [selectedMethod, setSelectedMethod] = useState('card');
    const [cardData, setCardData] = useState({ number: '', expiry: '', cvv: '' });
    const [errors, setErrors] = useState({});

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setCardData(prev => ({ ...prev, [name]: value }));
        // Clear error when user starts typing
        if (errors[name]) setErrors(prev => ({ ...prev, [name]: null }));
    };

    const validateAndProceed = () => {
        if (selectedMethod === 'card') {
            const newErrors = {};
            if (!cardData.number) newErrors.number = true;
            if (!cardData.expiry) newErrors.expiry = true;
            if (!cardData.cvv) newErrors.cvv = true;

            if (Object.keys(newErrors).length > 0) {
                setErrors(newErrors);
                return; // Stop here
            }
        }
        // If validation passes or PayPal is selected
        navigate('/checkout/review');
    };

    return (
        <div className="bg-background-light dark:bg-background-dark text-zinc-900 dark:text-zinc-100 font-display min-h-screen antialiased">
            {/* Promo Bar */}
            <div className="w-full bg-white text-[#10221c] text-[10px] uppercase tracking-[0.2em] py-2 text-center font-bold border-b border-gray-100">
                Join Club Lacoste to enjoy exclusive benefits!
            </div>

            <header className="sticky top-0 z-[100] bg-[#10221c] text-white">
                <div className="max-w-[1440px] mx-auto px-6 h-16 flex items-center justify-between">
                    <Link to="/" className="flex-shrink-0 flex items-center gap-2">
                        <div className="w-8 h-5 bg-white rounded-[2px] flex items-center justify-center">
                            <span className="material-icons-outlined text-[#10221c] text-sm">architecture</span>
                        </div>
                        <span className="text-xl font-extrabold tracking-tighter uppercase">L'Elegance</span>
                    </Link>
                </div>
            </header>

            <main className="max-w-7xl mx-auto px-6 py-12">
                {/* Progress Stepper */}
                <div className="mb-12 max-w-3xl">
                    <div className="flex items-center justify-between relative">
                        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-primary/10 -z-10 -translate-y-1/2"></div>
                        <div className="flex flex-col items-center gap-2 bg-background-light dark:bg-background-dark pr-4 cursor-pointer" onClick={() => navigate('/checkout')}>
                            <div className="w-10 h-10 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-lg shadow-primary/20">
                                <i className="material-icons text-sm">check</i>
                            </div>
                            <span className="text-xs font-semibold uppercase tracking-widest text-primary">Shipping</span>
                        </div>
                        <div className="flex flex-col items-center gap-2 bg-background-light dark:bg-background-dark px-4">
                            <div className="w-10 h-10 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-lg shadow-primary/20">2</div>
                            <span className="text-xs font-semibold uppercase tracking-widest text-primary">Payment</span>
                        </div>
                        <div className="flex flex-col items-center gap-2 bg-background-light dark:bg-background-dark pl-4">
                            <div className="w-10 h-10 rounded-full bg-white dark:bg-zinc-800 border-2 border-primary/20 text-zinc-400 flex items-center justify-center font-bold">3</div>
                            <span className="text-xs font-semibold uppercase tracking-widest text-zinc-400">Review</span>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col lg:flex-row gap-12">
                    <div className="flex-1 space-y-8">
                        <section>
                            <h1 className="text-3xl font-bold mb-2">Payment Method</h1>
                            <p className="text-zinc-500 dark:text-zinc-400">All transactions are secure and encrypted.</p>
                        </section>

                        <div className="space-y-4">
                            {/* Credit/Debit Card Option */}
                            <div className={`border rounded-xl transition-all ${selectedMethod === 'card' ? 'border-primary ring-2 ring-primary/20 bg-white dark:bg-zinc-900/50' : 'border-zinc-200 dark:border-zinc-800'}`}>
                                <label className="flex items-center justify-between p-6 cursor-pointer">
                                    <div className="flex items-center">
                                        <input
                                            type="radio"
                                            name="payment"
                                            checked={selectedMethod === 'card'}
                                            onChange={() => setSelectedMethod('card')}
                                            className="w-5 h-5 text-primary focus:ring-primary border-zinc-300"
                                        />
                                        <span className="ml-4 font-bold text-lg">Credit or Debit Card</span>
                                    </div>
                                    <div className="flex space-x-2 text-zinc-400">
                                        <span className="material-icons">credit_card</span>
                                    </div>
                                </label>

                                {selectedMethod === 'card' && (
                                    <div className="px-6 pb-8 space-y-6">
                                        <div className="relative">
                                            <label className="block text-[10px] font-bold uppercase tracking-widest text-zinc-500 mb-2">Card Number</label>
                                            <input
                                                name="number"
                                                value={cardData.number}
                                                onChange={handleInputChange}
                                                className={`w-full bg-background-light dark:bg-zinc-800 border-none rounded-lg p-4 focus:ring-2 focus:ring-primary transition-all ${errors.number ? 'ring-2 ring-red-500' : ''}`}
                                                placeholder="0000 0000 0000 0000"
                                                type="text"
                                            />
                                        </div>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <label className="block text-[10px] font-bold uppercase tracking-widest text-zinc-500 mb-2">Expiration</label>
                                                <input
                                                    name="expiry"
                                                    value={cardData.expiry}
                                                    onChange={handleInputChange}
                                                    className={`w-full bg-background-light dark:bg-zinc-800 border-none rounded-lg p-4 focus:ring-2 focus:ring-primary ${errors.expiry ? 'ring-2 ring-red-500' : ''}`}
                                                    placeholder="MM / YY"
                                                    type="text"
                                                />
                                            </div>
                                            <div>
                                                <label className="block text-[10px] font-bold uppercase tracking-widest text-zinc-500 mb-2">CVV</label>
                                                <input
                                                    name="cvv"
                                                    value={cardData.cvv}
                                                    onChange={handleInputChange}
                                                    className={`w-full bg-background-light dark:bg-zinc-800 border-none rounded-lg p-4 focus:ring-2 focus:ring-primary ${errors.cvv ? 'ring-2 ring-red-500' : ''}`}
                                                    placeholder="123"
                                                    type="password"
                                                />
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* PayPal Option */}
                            <div className={`border rounded-xl p-6 cursor-pointer transition-all ${selectedMethod === 'paypal' ? 'border-primary ring-2 ring-primary/20 bg-white dark:bg-zinc-900/50' : 'border-zinc-200 dark:border-zinc-800'}`}>
                                <label className="flex items-center justify-between cursor-pointer">
                                    <div className="flex items-center">
                                        <input
                                            type="radio"
                                            name="payment"
                                            checked={selectedMethod === 'paypal'}
                                            onChange={() => setSelectedMethod('paypal')}
                                            className="w-5 h-5 text-primary focus:ring-primary border-zinc-300"
                                        />
                                        <span className="ml-4 font-bold text-lg">PayPal</span>
                                    </div>
                                </label>
                            </div>
                        </div>
                    </div>

                    <aside className="w-full lg:w-[400px]">
                        <div className="sticky top-28 bg-white dark:bg-zinc-900 p-8 rounded-xl border border-zinc-200 dark:border-zinc-800 shadow-xl">
                            <h3 className="text-lg font-bold mb-6">Order Total</h3>
                            <div className="space-y-4 mb-8">
                                <div className="flex justify-between text-zinc-500">
                                    <span>Subtotal</span>
                                    <span className="font-medium">$255.00</span>
                                </div>
                                <div className="flex justify-between text-zinc-900 dark:text-white text-xl font-bold pt-4 border-t border-zinc-100 dark:border-zinc-800">
                                    <span>Total</span>
                                    <span>$277.31</span>
                                </div>
                            </div>

                            <button
                                onClick={validateAndProceed}
                                className="w-full bg-primary hover:bg-primary/90 text-white font-bold py-5 rounded-lg uppercase tracking-widest text-xs transition-all flex items-center justify-center space-x-2 shadow-lg shadow-primary/20"
                            >
                                <span>Review Order</span>
                                <i className="material-icons text-sm">arrow_forward</i>
                            </button>

                            {Object.keys(errors).length > 0 && (
                                <p className="mt-4 text-center text-red-500 text-xs font-bold animate-bounce">
                                    Please complete the payment details.
                                </p>
                            )}
                        </div>
                    </aside>
                </div>
            </main>
        </div>
    );
};

export default PaymentPage;
